from fastapi import FastAPI
from fastapi.responses import HTMLResponse, JSONResponse, Response

app = FastAPI()

HTML_PAGE = """<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Dieng Predict V18</title><style>body{background:#0a0e13;color:#fff;font-family:Arial;padding:10px}.header{background:linear-gradient(90deg,#00ff88,#00aaff);padding:14px;border-radius:12px;text-align:center;color:#000;font-weight:bold}.tabs{display:flex;gap:6px;margin:12px 0;overflow-x:auto}.tab{padding:10px 14px;border-radius:20px;background:#1e222b;color:#888;border:1px solid #333;cursor:pointer;white-space:nowrap}.tab.active{background:#00ff88;color:#000;font-weight:bold}.card{background:#151a22;border:1px solid #2a2e38;border-radius:14px;padding:14px;margin-top:12px}input,select{width:100%;padding:12px;border-radius:10px;border:1px solid #333;background:#1e222b;color:#fff;margin:5px 0}.btn{width:100%;padding:14px;background:#00ff88;color:#000;border:none;border-radius:12px;font-weight:bold;margin-top:10px}.badge{display:inline-block;padding:4px 10px;border-radius:15px;font-size:11px;margin:3px;font-weight:bold}.bg-green{background:#00ff8833;color:#00ff88;border:1px solid #00ff88}.bg-blue{background:#00aaff33;color:#00aaff;border:1px solid #00aaff}.bg-yellow{background:#ffcc0033;color:#ffcc00;border:1px solid #ffcc00}.stat{font-size:13px;color:#ccc;margin:4px 0}.stat b{color:#fff}.prob-bar{height:10px;background:#222;border-radius:5px;display:flex;overflow:hidden;margin:4px 0}.prob-bar div{height:100%}</style></head><body><div class="header">Dieng Predict V18 - MULTI SPORTS PRO</div><div class="tabs"><div class="tab active" onclick="switchTab('foot')">Football</div><div class="tab" onclick="switchTab('basket')">Basket</div><div class="tab" onclick="switchTab('tennis')">Tennis</div><div class="tab" onclick="switchTab('hockey')">Hockey Glace</div><div class="tab" onclick="switchTab('ping')">Tennis Table</div></div><div id="tab-foot" class="tab-content"><div class="card"><b>Football V1/V2/Nul + Forme Live</b><br><input id="footA" value="AEK Athenes"><input id="footB" value="Real Madrid"><button class="btn" onclick="analyseFoot()">ANALYSER FOOTBALL</button><div id="resFoot"></div></div></div><div id="tab-basket" class="tab-content" style="display:none"><div class="card"><b>Basket NBA/Euroleague</b><br><select id="basketLeague"><option>NBA</option><option>Euroleague</option></select><input id="basketA" value="Lakers"><input id="basketB" value="Warriors"><button class="btn" onclick="analyseBasket()">ANALYSER BASKET</button><div id="resBasket"></div></div></div><div id="tab-tennis" class="tab-content" style="display:none"><div class="card"><b>Tennis ATP/WTA</b><br><select id="tennisSurface"><option>Dur</option><option>Terre battue</option><option>Gazon</option></select><input id="tennisA" value="Alcaraz"><input id="tennisB" value="Sinner"><button class="btn" onclick="analyseTennis()">ANALYSER TENNIS</button><div id="resTennis"></div></div></div><div id="tab-hockey" class="tab-content" style="display:none"><div class="card"><b>Hockey NHL</b><br><input id="hockeyA" value="Maple Leafs"><input id="hockeyB" value="Oilers"><button class="btn" onclick="analyseHockey()">ANALYSER HOCKEY</button><div id="resHockey"></div></div></div><div id="tab-ping" class="tab-content" style="display:none"><div class="card"><b>Ping Pong</b><br><input id="pingA" value="Fan Zhendong"><input id="pingB" value="Harimoto"><button class="btn" onclick="analysePing()">ANALYSER PING</button><div id="resPing"></div></div></div><script>function switchTab(t){document.querySelectorAll('.tab-content').forEach(function(c){c.style.display='none'});document.querySelectorAll('.tab').forEach(function(c){c.classList.remove('active')});document.getElementById('tab-'+t).style.display='block';event.target.classList.add('active');}var FOOT_DB={"real madrid":{forme:1.18,elo:1915,abs:["Rodrygo OUT","Asencio OUT"],but:2.15},"aek athenes":{forme:0.83,elo:1620,abs:["Strakosha doute"],but:1.05}};function getFoot(n){var k=n.toLowerCase().trim();if(FOOT_DB[k])return FOOT_DB[k];for(var x in FOOT_DB){if(k.indexOf(x)>=0)return FOOT_DB[x];}return{forme:0.95,elo:1650,abs:["A verifier"],but:1.35};}function calcProb(eA,eB,fA,fB){var d=(eA-eB)+(fA-fB)*100;var pA=1/(1+Math.pow(10,-d/400));var pB=1-pA;var dr=0.24-Math.abs(pA-0.5)*0.2;if(dr<0.12)dr=0.12;return{v1:pA*(1-dr)*100,nul:dr*100,v2:pB*(1-dr)*100};}function analyseFoot(){var a=document.getElementById('footA').value;var b=document.getElementById('footB').value;var A=getFoot(a);var B=getFoot(b);var p=calcProb(A.elo,B.elo,A.forme,B.forme);var xg=(A.but*A.forme+B.but*B.forme)/1.1;var html='<div style="margin-top:10px"><span class="badge bg-green">V1 '+a+': '+p.v1.toFixed(1)+'%</span><span class="badge bg-yellow">Nul: '+p.nul.toFixed(1)+'%</span><span class="badge bg-blue">V2 '+b+': '+p.v2.toFixed(1)+'%</span><div class="prob-bar"><div style="width:'+p.v1+'%;background:#00ff88"></div><div style="width:'+p.nul+'%;background:#ffcc00"></div><div style="width:'+p.v2+'%;background:#00aaff"></div></div><div class="stat"><b>Forme:</b> '+A.forme+' vs '+B.forme+'</div><div class="stat"><b>Absences:</b> '+A.abs.join(', ')+' | '+B.abs.join(', ')+'</div><div class="stat"><b>xG:</b> '+xg.toFixed(2)+'</div></div>';document.getElementById('resFoot').innerHTML=html;}function analyseBasket(){var a=document.getElementById('basketA').value;var b=document.getElementById('basketB').value;var v1=50+Math.random()*20;var v2=100-v1;document.getElementById('resBasket').innerHTML='<span class="badge bg-green">V1 '+a+': '+v1.toFixed(1)+'%</span><span class="badge bg-blue">V2 '+b+': '+v2.toFixed(1)+'%</span>';}function analyseTennis(){var a=document.getElementById('tennisA').value;var b=document.getElementById('tennisB').value;var v1=52+Math.random()*10;document.getElementById('resTennis').innerHTML='<span class="badge bg-green">V1 '+a+': '+v1.toFixed(1)+'%</span><span class="badge bg-blue">V2 '+b+': '+(100-v1).toFixed(1)+'%</span>';}function analyseHockey(){var a=document.getElementById('hockeyA').value;var b=document.getElementById('hockeyB').value;var v1=38+Math.random()*10;document.getElementById('resHockey').innerHTML='<span class="badge bg-green">V1 '+a+': '+v1.toFixed(1)+'%</span><span class="badge bg-blue">V2 '+b+': '+(62-v1).toFixed(1)+'%</span>';}function analysePing(){var a=document.getElementById('pingA').value;var b=document.getElementById('pingB').value;var v1=55+Math.random()*10;document.getElementById('resPing').innerHTML='<span class="badge bg-green">V1 '+a+': '+v1.toFixed(1)+'%</span><span class="badge bg-blue">V2 '+b+': '+(100-v1).toFixed(1)+'%</span>';}</script></body></html>"""

@app.get('/manifest.json')
def manifest():
    return JSONResponse({'name':'Dieng Predict V18','short_name':'Dieng V18','start_url':'/','display':'standalone','background_color':'#0a0e13','theme_color':'#00ff88'})

@app.get('/sw.js')
def sw():
    return Response(content="self.addEventListener('fetch',function(e){});", media_type="application/javascript")

@app.get('/', response_class=HTMLResponse)
def home():
    return HTMLResponse(content=HTML_PAGE, status_code=200)
